from typing import Dict
from datetime import datetime


def header_banner(project_version: str) -> str:
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return "\n".join(
        [
            '"""',
            "AUTO-GENERATED JoinQuant Strategy (FactorPilot)",
            f"Generated at: {ts}",
            f"Version: {project_version}",
            "",
            "WARNING: This file is generated by tools/build_jq_strategy.py.",
            "Do not edit manually; edit source modules in factors/ and utils/ instead.",
            '"""',
        ]
    )


def compose_imports_block(needs_typing: bool) -> str:
    base = [
        "import math",
        "import sys",
        "import types",
        "from datetime import date, datetime, timedelta",
        "import numpy as np",
        "import pandas as pd",
    ]
    if needs_typing:
        base.insert(0, "from typing import List, Dict, Set, Tuple, Union, Optional")
    return "\n".join(base)


def compose_dependencies_block(dep_map: Dict) -> str:
    import json

    # Ensure sets become lists for JSON dump then back to Python literal
    def _convert(obj):
        if isinstance(obj, set):
            return sorted(list(obj))
        if isinstance(obj, dict):
            return {k: _convert(v) for k, v in obj.items()}
        if isinstance(obj, (list, tuple)):
            return [_convert(x) for x in obj]
        return obj

    converted = _convert(dep_map)
    text = "FACTOR_DEPENDENCIES = " + json.dumps(
        converted, ensure_ascii=False, indent=2
    )
    return text


def compose_mapping_block(cloud_mapping=None) -> str:
    import json

    mapping_json = repr(cloud_mapping or {})
    return f"""
# ---- Cloud API Mapping ----
CLOUD_API_MAPPING = {mapping_json}
"""


def compose_adapter_block(cloud_mapping=None) -> str:
    from pathlib import Path

    source = Path(__file__).resolve().parents[2] / "utils/jq_factor_adapter.py"
    return (
        source.read_text(encoding="utf-8")
        .replace("CLOUD_API_MAPPING = {}", "", 1)
        .replace("from utils.pit import apply_pit_adjustment", "")
        .replace("from utils.pit import normalize_price_money", "")
    )


def compose_runtime_shims_block() -> str:
    import inspect

    base_shims = """
# ---- runtime import shims for single-file environment ----
import sys as __sys
import types as __types

# Provide jq_adapter with jit/njit/prange and environment flag
try:
    __jq_mod = __types.ModuleType('jq_adapter')
    __jq_mod.jit = conditional_jit
    __jq_mod.njit = conditional_jit
    __jq_mod.prange = prange
    __jq_mod.IS_JOINQUANT = True
    __sys.modules['jq_adapter'] = __jq_mod
    # utils package and utils.jq_adapter alias
    __sys.modules.setdefault('utils', __types.ModuleType('utils'))
    __sys.modules['utils.jq_adapter'] = __jq_mod
except Exception:
    pass

# Provide factor_base module exposing FactorBase class
try:
    __fb_mod = __types.ModuleType('factor_base')
    __fb_mod.FactorBase = 'FactorBase' in globals() and FactorBase or None
    __sys.modules['factor_base'] = __fb_mod
    # utils.factor_base alias
    __sys.modules.setdefault('utils', __types.ModuleType('utils'))
    __sys.modules['utils.factor_base'] = __fb_mod
except Exception:
    pass

del __sys, __types
"""
    # Append sources of helper functions
    src = base_shims
    # We need to make sure these functions are defined when this runs
    funcs = [
        __jq_fetch_price_data,
        __jq_patched_fetch_raw_data,
        _patch_factor_base,  # We will define this wrapper
        _patch_subclasses,  # We will define this wrapper
    ]

    for f in funcs:
        try:
            src += "\n" + inspect.getsource(f)
        except Exception as e:
            print(f"Error getting source for {f.__name__}: {e}")

    # Add calls to the patchers
    src += "\n_patch_factor_base()"
    src += "\n_patch_subclasses()"

    return src


# ---- Definitions of helper functions used in runtime shims ----


def __jq_fetch_price_data(factor_self, fields):
    import pandas as pd

    securities = getattr(factor_self, "all_stocks", None) or getattr(
        factor_self, "stock_pool", []
    )
    start = getattr(factor_self, "start_date", None)
    end = getattr(factor_self, "end_date", None)
    if not securities or start is None or end is None:
        raise ValueError("factor_input_range_missing")
    freq = getattr(factor_self, "data_frequency", "daily")
    adapter = JQFactorAdapter(
        {},
        freq=freq,
        strict=True,
        allow_field_fallback=False,
        use_expanding_window=True,
        expanding_start_date=start,
    )
    result = adapter.fetch_price(securities, end, fields)
    return result[pd.to_datetime(result.date) >= pd.Timestamp(start)].copy()


def __jq_patched_fetch_raw_data(self, fields, table_name=None):
    return __jq_fetch_price_data(self, fields)


# Helper wrapper for patching FactorBase
def _patch_factor_base():
    try:
        if "FactorBase" in globals() and FactorBase is not None:
            print("[DEBUG] Patching FactorBase._fetch_raw_data...")
            FactorBase._fetch_raw_data = __jq_patched_fetch_raw_data
            print("[DEBUG] FactorBase._fetch_raw_data patched successfully")
        else:
            print("[DEBUG] FactorBase not found in globals or is None!")
    except Exception as e:
        print(f"[DEBUG] Failed to patch FactorBase: {e}")
        pass


# Helper wrapper for patching subclasses
def _patch_subclasses():
    # Patch custom optimized fetch methods in subclasses to use the standard (patched) _fetch_raw_data
    def __jq_patched_fetch_5min_raw_data_optimized(self, fields):
        # Redirect to standard _fetch_raw_data which is already patched to use JQ API
        return self._fetch_raw_data(fields, table_name="price_data")

    try:
        for name, cls in list(globals().items()):
            if (
                isinstance(cls, type)
                and issubclass(cls, FactorBase)
                and cls is not FactorBase
            ):
                if hasattr(cls, "_fetch_5min_raw_data_optimized"):
                    cls._fetch_5min_raw_data_optimized = (
                        __jq_patched_fetch_5min_raw_data_optimized
                    )
    except Exception:
        pass


def compose_strategy_entry_block(default_factor: str, freq: str, window: int, index: str = "000300.XSHG") -> str:
    return f"""
# ---- PIT Mode Configuration ----
# Set to 'backtest' (default, uses JQ dynamic PIT with fq='pre')
# or 'research' (uses Dynamic PIT with fq=None + factor/factor_end)
PIT_MODE = 'backtest'

def initialize(context):
    context.default_factor = '{default_factor}'
    context.freq = '{freq}'
    context.window = {window}
    context.adapter = JQFactorAdapter(FACTOR_DEPENDENCIES, freq=context.freq, window=context.window, strict=True, allow_field_fallback=False, min_full_day_tolerance=2, pit_mode=PIT_MODE)
    # Bind external get_price if provided (global or on context)
    try:
        if 'EXTERNAL_GET_PRICE' in globals() and callable(EXTERNAL_GET_PRICE):
            context.adapter.set_get_price(EXTERNAL_GET_PRICE)
    except Exception:
        pass
    try:
        if hasattr(context, 'get_price_fn') and callable(getattr(context, 'get_price_fn', None)):
            context.adapter.set_get_price(context.get_price_fn)
    except Exception:
        pass
    # Bind external get_factor_values for cloud factor data fetching
    try:
        from jqfactor import get_factor_values
        set_external_get_factor_values(get_factor_values)
    except Exception:
        pass
    # Bind external get_valuation for cloud factor data fetching
    try:
        set_external_get_valuation(get_valuation)
    except Exception:
        pass
    # Bind external get_price for cloud price data fetching
    try:
        set_external_get_price(get_price)
    except Exception:
        pass
    # Per-factor windows injected at build time (optional)
    context.factor_windows = FACTOR_REQUIRED_WINDOWS if 'FACTOR_REQUIRED_WINDOWS' in globals() else {{}}
    # Per-factor runtime hints injected at build time (optional)
    context.factor_hints = FACTOR_RUNTIME_HINTS if 'FACTOR_RUNTIME_HINTS' in globals() else {{}}

def before_trading_start(context):
    pass

def handle_data(context, data):
    factor_name = context.default_factor
    securities = list(get_index_stocks({index!r}, date=context.previous_date))
    result = compute_factor_batch(
        {{factor_name: globals().get(factor_name)}}, FACTOR_REQUIREMENTS,
        FACTOR_DEPENDENCIES, securities, str(context.previous_date), JQFactorAdapter,
        windows=FACTOR_REQUIRED_WINDOWS,
        pool_history=getattr(context, 'monthly_stock_pools', None),
    )
    log.info("factor {{}} computed shape={{}}".format(factor_name, result.shape))

def after_trading_end(context):
    pass
""".strip()
